// Each lambda has a unique, unutterable type.
auto my_lambda = [](int x) { return x > 5; };

// To store it generically, one might use std::function.
// This adds overhead: potential heap allocation, and an indirect call.
#include <functional>
std::function<bool(int)> func = my_lambda;

// Using auto is direct, efficient, and has no overhead.
// The compiler knows the exact type and can inline the call.
auto derefUPLess = [](const auto& p1, const auto& p2) {
    return *p1 < *p2;
};

bool b1 = func(10);        // Invocation via type-erasing wrapper.
bool b2 = my_lambda(10);   // Direct, potentially inlined call.
